/*
 * story-road-events — the level-capped wandering story events: cross-village
 * mini-stories brought to the player by road NPCs (docs/fable-5-story-rebuild.md
 * §10 table; 15 events, levels 22-100). Delivered on the world map: the next
 * eligible event's NPC walks the player's current sector; talking to them opens
 * a multi-page VN whose choice is recorded to the server story record.
 *
 * ZERO imports on purpose — the api parity test (api/_story-road-events.test.ts)
 * imports this file directly under node/tsx. Wanderer synthesis and CreatorEvent
 * conversion live in lib/story-road-events.ts.
 *
 * Completion is trait-presence: a player owns exactly one rd<level>-* trait per
 * event, granted at choice time (so a battle loss never loses the story beat).
 * Seat of Scars (level 100) additionally requires the Kage finale
 * (minProgress 9); everything else is level-gated only.
 */

export type StoryRoadLane = "good" | "neutral" | "bad";
export type StoryRoadBattle = { bossName: string; bossIcon: string };
export type StoryRoadChoice = {
    text: string;
    conclusion: string;
    trait: string;
    lane: StoryRoadLane;
    nextPage: number;
    battle?: StoryRoadBattle;
};
export type StoryRoadPage = {
    title: string;
    scene: string;
    speaker: string;
    dialogue: string[];
    choices?: StoryRoadChoice[];
};
export type StoryRoadNpcArchetype =
    | "courier" | "tracker" | "trainer" | "pilgrim" | "emissary"
    | "broker" | "official" | "soldier" | "rival";
export type StoryRoadEvent = {
    id: string;
    slug: string;
    levelReq: number;
    /** Milestone chapters required first (only Seat of Scars uses this: 9 = post-finale). */
    minProgress: number;
    title: string;
    npcName: string;
    npcArchetype: StoryRoadNpcArchetype;
    pages: StoryRoadPage[];
};

function pg(title: string, scene: string, speaker: string, ...dialogue: string[]): StoryRoadPage {
    return { title, scene, speaker, dialogue };
}

function ch(text: string, lane: StoryRoadLane, trait: string, conclusion: string, battle?: StoryRoadBattle): Omit<StoryRoadChoice, "nextPage"> {
    return { text, lane, trait, conclusion, battle };
}

function roadEvent(levelReq: number, slug: string, title: string, npcName: string, npcArchetype: StoryRoadNpcArchetype, pages: StoryRoadPage[], choices: Omit<StoryRoadChoice, "nextPage">[]): StoryRoadEvent {
    const last = pages.length - 1;
    return {
        id: `story-road-${slug}`,
        slug,
        levelReq,
        minProgress: levelReq >= 100 ? 9 : 0,
        title,
        npcName,
        npcArchetype,
        // Choices sit on the final page, self-pointing: a battle choice closes
        // the scene into the arena; a non-battle choice concludes it in place.
        pages: pages.map((page, index) => index === last ? { ...page, choices: choices.map((choice) => ({ ...choice, nextPage: last })) } : page),
    };
}

